using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class WindDesignForm {
 readonly HashSet<string> buildingKeys=new HashSet<string>();
 readonly DataGridView pressureGrid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells};
 readonly Label pressureStatus=new Label{Dock=DockStyle.Top,Height=54,Padding=new Padding(12)};
 void AddBuildingInputs(){
  var panel=Section("Building inputs","Directional MWFRS pressure calculations for enclosed / partially enclosed gable, hip or flat-roof rectangular buildings. Enter actual dimensions. Ridge direction fixes the four building axes; terrain is assessed in eight compass directions.");
  Toggle(panel,"BuildingEnabled","Include building wind pressures",false);
  NumberField(panel,"BuildingWidth","Building width across ridge (m)","");NumberField(panel,"BuildingLength","Building length along ridge (m)","");NumberField(panel,"Eave","Eave height (m)","");NumberField(panel,"Apex","Apex height (m); equal eave for flat roof","");
  Choice(panel,"RidgeDirection","Ridge alignment (compass line of the ridge / long axis; see the outline on the site map)",new[]{"N–S","NE–SW","E–W","NW–SE","Other azimuth (type it below)"});
  /* any azimuth (owner, 25 November 2026: "All yung building rotation ialign sa different azimuth") */NumberField(panel,"RidgeAzimuth","Ridge azimuth (degrees clockwise from north, 0–180)","");/* owner (24 November 2026, "yung ridge alignment dapat mag suggest"): the alignment giving the largest design pressures is suggested */panel.Controls.Add(ridgeHint);ridgeUse.LinkClicked+=(s,e)=>{if(suggestedRidge>=0)SetRidge(suggestedRidge);};panel.Controls.Add(ridgeUse);Choice(panel,"BuildingSystem","Structural system",new[]{"MRF Steel","MRF Concrete","Other system"});Choice(panel,"Enclosure","Enclosure classification",new[]{"Enclosed","Partially enclosed"});
  Toggle(panel,"AutoG","Calculate gust effect factor G",true);NumberField(panel,"UserG","G when automatic gust is unchecked","0.85");NumberField(panel,"Damping","Damping ratio for flexible response","0.02");NumberField(panel,"FrequencyN","Natural frequency normal (Hz); 0 = estimate","0");NumberField(panel,"FrequencyP","Natural frequency parallel (Hz); 0 = estimate","0");NumberField(panel,"OpeningHeight","Positive internal qi height (m); 0 = mean roof","0");/* the STAAD model (owner, 24 November 2026: "ilagay yung x z dimension na pinaginput ko sa staad saka mamimili ng orientation tapos
     saka mo aayusin yung loads at yung copy paste ko para alam kong WW+X LW+X"): +X bearing, ridge axis and the X / Z dimensions set the
     building width, length and ridge alignment and give every load its STAAD axis and sign */
   /* components and cladding elements (owner: "gawa ka naman ng for C&C") */
   NumberField(panel,"CCElements","C&C elements: name @ effective wind area m² (span × max(width, span/3))","Roof sheet / fastener @ 0.93, Purlin @ 9.3, Wall sheet / fastener @ 0.93, Girt @ 9.3");EnableWhen(()=>On("BuildingEnabled"),"CCElements");
   panel.Controls.Add(new Label{Text="STAAD model orientation",Width=420,Height=26,Font=ModernUi.Strong,ForeColor=PowTheme.Ink,Padding=new Padding(0,8,0,0)});
   /* owner (25 November 2026: "yung ridge naka align sa x direction ni staad. diko gets yung +x axis"): the STAAD +X can be given against
     the ridge - along it toward the ridge azimuth or the other way, or across it - instead of a compass bearing */
   Choice(panel,"StaadXDir","STAAD +X axis (the direction X coordinates increase in the model)",new[]{"Not used","Along the ridge, toward the ridge azimuth","Along the ridge, toward the opposite end (azimuth + 180°)","Across the ridge (azimuth + 90°)","Across the ridge (azimuth − 90°)","N","NE","E","SE","S","SW","W","NW","Other bearing (type it below)"});NumberField(panel,"StaadXBearing","+X bearing of the STAAD model (degrees clockwise from north)","");Choice(panel,"StaadRidgeAxis","Ridge runs along STAAD",new[]{"X","Z"});
   NumberField(panel,"StaadX","Building dimension along STAAD X (m)","");NumberField(panel,"StaadZ","Building dimension along STAAD Z (m)","");panel.Controls.Add(staadAxisHint);
   foreach(var key in new[]{"StaadXDir","StaadXBearing","StaadRidgeAxis","StaadX","StaadZ","RidgeDirection","RidgeAzimuth"}){var c=Inputs[key];var combo=c as ComboBox;if(combo!=null)combo.SelectedIndexChanged+=(s,e)=>{if(!Restoring)ApplyStaadOrientation();};else c.TextChanged+=(s,e)=>{if(!Restoring)ApplyStaadOrientation();};}
   EnableWhen(()=>On("BuildingEnabled"),"Eave","Apex","BuildingSystem","Enclosure","AutoG","StaadXDir");EnableWhen(()=>On("BuildingEnabled")&&StaadBearing()<0,"BuildingWidth","BuildingLength");EnableWhen(()=>On("BuildingEnabled")&&(StaadBearing()<0||RelativeStaad()),"RidgeDirection");EnableWhen(()=>On("BuildingEnabled")&&(StaadBearing()<0||RelativeStaad())&&Value("RidgeDirection").StartsWith("Other"),"RidgeAzimuth");EnableWhen(()=>On("BuildingEnabled")&&Value("StaadXDir").StartsWith("Other"),"StaadXBearing");EnableWhen(()=>On("BuildingEnabled")&&StaadBearing()>=0&&!RelativeStaad(),"StaadRidgeAxis");EnableWhen(()=>On("BuildingEnabled")&&StaadBearing()>=0,"StaadX","StaadZ");EnableWhen(()=>On("BuildingEnabled")&&!On("AutoG"),"UserG");EnableWhen(()=>On("BuildingEnabled")&&On("AutoG"),"Damping","FrequencyN","FrequencyP");EnableWhen(()=>On("BuildingEnabled")&&Value("Enclosure")=="Partially enclosed","OpeningHeight");
  foreach(string key in Inputs.Keys.Where(x=>!new[]{"Latitude","Longitude","Category","Height","Kd","Reviewed"}.Contains(x)).ToArray()){
   buildingKeys.Add(key);var check=Inputs[key] as CheckBox;var combo=Inputs[key] as ComboBox;
   if(check!=null)check.CheckedChanged+=(s,e)=>{if(!Restoring)UpdatePressureResults();};else if(combo!=null)combo.SelectedIndexChanged+=(s,e)=>{if(!Restoring)UpdatePressureResults();};else Inputs[key].TextChanged+=(s,e)=>{if(!Restoring)UpdatePressureResults();};
  }
  AddBuildingModel(panel);
  var page=new TabPage("Main Wind Force Resisting System (MWFRS)");foreach(string column in new[]{"Wind from / axis","Surface","Load case","Exposure","z (m)","Kz","Kzt","q (kPa)","qh (kPa)","qi (kPa)","G","Cp","GCpi","p (kPa)"})pressureGrid.Columns.Add(column,column);
  pressureGrid.Columns[0].MinimumWidth=150;pressureGrid.Columns[1].MinimumWidth=150;pressureGrid.Columns[2].MinimumWidth=260;
  page.Controls.Add(pressureGrid);page.Controls.Add(pressureStatus);AddResultPage(page);pressureStatus.Text="Enter building geometry and enable building wind pressures. p = q G Cp − qi (GCpi).";
 }
 readonly Label staadAxisHint=new Label{Width=420,Height=64,ForeColor=PowTheme.Muted,Text="Choose how the model's +X runs: along the ridge (toward the ridge azimuth or the other way) or across it. +X is the direction the X coordinates grow in STAAD (the X arrow of the axis triad); Y is up and +Z is 90° clockwise from +X on plan."};
 /* bearing of the STAAD +X axis in degrees, or -1 when not used */
 bool RelativeStaad(){string v=Value("StaadXDir");return v.StartsWith("Along")||v.StartsWith("Across");}
 internal double StaadBearing(){string[] d={"N","NE","E","SE","S","SW","W","NW"};string v=Value("StaadXDir");
  if(v.StartsWith("Along")||v.StartsWith("Across")){double az=RidgeAzimuthInput();if(double.IsNaN(az))return -1;return WindBuildingLoads.Norm(az+(v.Contains("opposite")?180:v.Contains("+ 90")?90:v.Contains("− 90")?270:0));}if(v.StartsWith("Other")){double b;return double.TryParse(Value("StaadXBearing"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out b)&&WindTin.Finite(b)?WindBuildingLoads.Norm(b):-1;}int i=Array.IndexOf(d,v);return i<0?-1:i*45;}
 /* the ridge azimuth from the inputs (NaN while "Other" has no valid number) */
 double RidgeAzimuthInput(){int i=((ComboBox)Inputs["RidgeDirection"]).SelectedIndex;if(i>=0&&i<4)return i*45;double a;return double.TryParse(Value("RidgeAzimuth"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out a)&&WindTin.Finite(a)?(a%180+180)%180:double.NaN;}
 void SetRidge(double az){az=(az%180+180)%180;double k=az/45;var combo=(ComboBox)Inputs["RidgeDirection"];if(Math.Abs(k-Math.Round(k))<1e-6)combo.SelectedIndex=(int)Math.Round(k)%4;else{Inputs["RidgeAzimuth"].Text=az.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture);combo.SelectedIndex=4;}}
 /* the first assessed terrain bearing: the building's faces and diagonals when the building is on (ridge azimuth mod 45), else north */
 internal double TerrainOffset(){if(!BuildingEnabled)return 0;double a=RidgeAzimuthInput();if(double.IsNaN(a))return 0;double o=(a%45+45)%45;return o<1e-6||o>45-1e-6?0:o;}
 internal string RidgeLabel(){double a=RidgeAzimuthInput();return double.IsNaN(a)?Value("RidgeDirection"):WindBuildingLoads.RidgeName(a);}
 void ApplyStaadOrientation(){double xb=StaadBearing();if(xb<0){staadAxisHint.Text=RelativeStaad()?"Enter the ridge azimuth first.":"Choose how the model's +X runs: along the ridge (toward the ridge azimuth or the other way) or across it. +X is the direction the X coordinates grow in STAAD (the X arrow of the axis triad); Y is up and +Z is 90° clockwise from +X on plan.";return;}
  double x,z;bool ridgeX;if(RelativeStaad()){ridgeX=Value("StaadXDir").StartsWith("Along");var axis=(ComboBox)Inputs["StaadRidgeAxis"];if(axis.SelectedIndex!=(ridgeX?0:1))axis.SelectedIndex=ridgeX?0:1;}
  else{ridgeX=Value("StaadRidgeAxis")!="Z";double ridge=((ridgeX?xb:xb+90)%180+180)%180;SetRidge(ridge);}
  string zDir=WindBuildingLoads.BearingName(xb+90);
  if(double.TryParse(Value("StaadX"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out x)&&double.TryParse(Value("StaadZ"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out z)&&x>0&&z>0){
   Inputs["BuildingLength"].Text=(ridgeX?x:z).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture);Inputs["BuildingWidth"].Text=(ridgeX?z:x).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture);}
  staadAxisHint.Text="+X → "+WindBuildingLoads.BearingName(xb)+", +Z → "+zDir+". Ridge along "+(ridgeX?"X":"Z")+" = "+RidgeLabel()+"; length along the ridge and width across it come from the X / Z dimensions.";}
 readonly Label ridgeHint=new Label{Width=420,Height=46,ForeColor=PowTheme.Teal,Text="Suggested ridge alignment: load the site terrain and enter the building to get a suggestion."};
 readonly LinkLabel ridgeUse=new LinkLabel{Width=420,Height=22,Text="Use the suggested ridge alignment",Enabled=false};double suggestedRidge=double.NaN;
 /* the alignment whose governing |p| is the largest (the critical orientation when the real one is not fixed) */
 /* every azimuth 0-175° in 5° steps is tried; the largest governing |p| is suggested, with the four compass alignments listed */
 void SuggestRidge(){suggestedRidge=double.NaN;ridgeUse.Enabled=false;string[] names={"N–S","NE–SW","E–W","NW–SE"};
  try{if(!BuildingEnabled||terrain==null){ridgeHint.Text="Suggested ridge alignment: load the site terrain and enable building wind pressures to get a suggestion.";return;}
   var b=Building();PressureRows(b);double v=WindTin.At(Number("Latitude"),Number("Longitude"),Value("Category")).V;var dirs=WindAssessment.Calculate(terrain,b.Height,v,b.Kd);
   var az=Enumerable.Range(0,36).Select(k=>k*5.0).ToArray();var all=WindBuildingLoads.AzimuthPeaks(b,v,dirs,az);int best=WindBuildingLoads.SuggestedRidge(all);suggestedRidge=az[best];
   double now=RidgeAzimuthInput();ridgeUse.Enabled=double.IsNaN(now)||Math.Abs(now-suggestedRidge)>1e-6;
   ridgeHint.Text="Suggested: "+WindBuildingLoads.RidgeName(az[best])+" (largest design pressure |p| = "+F(all[best])+" kPa, every 5° checked). "+string.Join(" · ",Enumerable.Range(0,4).Select(k=>names[k]+" "+F(all[k*9])))+" kPa. Use the actual ridge orientation when it is known.";}
  catch(Exception ex){ridgeHint.Text="Suggested ridge alignment: "+ex.Message;}}
 WindBuildingInput Building(){var b=new WindBuildingInput{Width=Number("BuildingWidth"),Length=Number("BuildingLength"),Eave=Number("Eave"),Apex=Number("Apex"),Kd=Number("Kd"),System=Value("BuildingSystem"),Enclosure=Value("Enclosure"),RidgeDirection=Math.Max(0,Math.Min(3,((ComboBox)Inputs["RidgeDirection"]).SelectedIndex)),Azimuth=((ComboBox)Inputs["RidgeDirection"]).SelectedIndex==4?RequireAzimuth():double.NaN,AutoG=((CheckBox)Inputs["AutoG"]).Checked,UserG=Number("UserG"),Damping=Number("Damping"),FrequencyNormal=Number("FrequencyN"),FrequencyParallel=Number("FrequencyP"),OpeningHeight=Number("OpeningHeight")};b.Validate();return b;}
 double RidgeAzimuthOrThrow(){double a=RidgeAzimuthInput();if(double.IsNaN(a))throw new Exception("Enter the ridge azimuth in degrees (0–180), or choose a compass alignment.");return a;}
 double RequireAzimuth(){return RidgeAzimuthOrThrow();}
 bool BuildingEnabled{get{return Inputs.ContainsKey("BuildingEnabled")&&((CheckBox)Inputs["BuildingEnabled"]).Checked;}}
 List<WindPressureRow> PressureRows(WindBuildingInput b){if(terrain==null)throw new Exception("Load site terrain before calculating building pressures.");if(Math.Abs(terrain.Lat-Number("Latitude"))>1e-8||Math.Abs(terrain.Lon-Number("Longitude"))>1e-8)throw new Exception("Terrain snapshot does not match the project coordinates.");double v=WindTin.At(Number("Latitude"),Number("Longitude"),Value("Category")).V;return WindBuildingLoads.Calculate(b,v,WindAssessment.Calculate(terrain,b.Height,v,b.Kd));}
 /* the building outline on the site map follows the width, length and ridge alignment */
 void ShowBuildingOnMap(){double w=0,l=0;bool ok=BuildingEnabled&&double.TryParse(Value("BuildingWidth"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out w)&&double.TryParse(Value("BuildingLength"),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out l)&&w>0&&l>0;
  if(!ok){siteMap.SetBuilding(0,0,double.NaN);return;}siteMap.SetBuilding(w,l,RidgeAzimuthInput());}
 DataGridView ccGrid;Label ccStatus;
 void AddCcPage(){var page=new TabPage("Components and Cladding (C&C)");ccGrid=ReadOnlyGrid("Element","A (m²)","Zone","GCp +","GCp −","p + (kPa)","p − (kPa)");ccStatus=new Label{Dock=DockStyle.Top,Height=64,Padding=new Padding(8),ForeColor=PowTheme.Muted};page.Controls.Add(ccGrid);page.Controls.Add(ccStatus);AddResultPage(page);}
 void UpdateCc(List<WindPressureRow> rows,WindBuildingInput b){if(ccGrid==null)return;ccGrid.Rows.Clear();if(rows==null){ccStatus.Text="Enable building wind pressures and load the site terrain to get the C&C pressures.";return;}
  try{double v=WindTin.At(Number("Latitude"),Number("Longitude"),Value("Category")).V;var s=WindComponentsCladding.Calculate(b,rows,Value("CCElements"),WindAssessment.Calculate(terrain,b.Height,v,b.Kd),v);foreach(var r in s.Rows)ccGrid.Rows.Add(r.Element,F(r.Area),r.Zone,F(r.GCpPos),F(r.GCpNeg),"+"+F(r.PPos),F(r.PNeg));WindLink.Save(s,Value("Latitude")+" N, "+Value("Longitude")+" E");/* the Purlin Design sheet reads this (owner: "automatic link ng loads sa purlin design") */
   ccStatus.ForeColor=PowTheme.Teal;ccStatus.Text="NSCP 2015 Section 207E Part 1: p = qh [(GCp) − (GCpi)], qh = "+F(s.Qh)+" kPa (wind from "+s.Direction+", exposure "+s.Exposure+"), a = "+F(s.A)+" m, roof "+s.RoofRange+", GCpi ±"+F(s.GCpi)+". Zones: roof 1 interior / 2 edges / 3 corners, walls 4 interior / 5 corners. Minimum ±0.77 kPa. "+s.Note;}
  catch(Exception ex){ccStatus.ForeColor=Color.Firebrick;ccStatus.Text="C&C: "+ex.Message;}}
 void UpdatePressureResults(){RefreshStaadWind();ShowBuildingOnMap();SuggestRidge();pressureGrid.Rows.Clear();if(buildingModel!=null){buildingModel.Pressures=null;buildingModel.Invalidate();}if(!BuildingEnabled){pressureStatus.Text="Building wind pressures are off. Enter dimensions and enable them in Building inputs.";UpdateCc(null,null);return;}try{var b=Building();var rows=PressureRows(b);UpdateCc(rows,b);if(buildingModel!=null){buildingModel.Pressures=rows;buildingModel.Invalidate();}foreach(var r in rows){int n=pressureGrid.Rows.Add(r.Direction,r.Surface,r.Case,r.Exposure,F(r.Z),F(r.Kz),F(r.Kzt),F(r.Q),F(r.Qh),F(r.Qi),F(r.G),F(r.Cp),F(r.GCpi),F(r.P));pressureGrid.Rows[n].Cells[3].Style.ForeColor=WindColors.Roughness(r.Exposure);}
   int axes=rows.Select(r=>r.Direction).Distinct().Count();pressureStatus.Text="p = q G Cp − qi (GCpi) | "+axes+" of 4 principal axes resolved | h="+F(b.Height)+"m; roof slope="+F(b.Angle)+"° | Positive toward surface; negative away. Gross pressures; apply MWFRS minimums / load patterns separately.";
   /* the terrain was assessed for another orientation: say so (exposure and Kzt of each face need the terrain loaded for the faces) */
   if(terrain!=null&&Math.Abs(terrain.Offset-TerrainOffset())>1e-6)pressureStatus.Text+=" Terrain directions do not follow the building faces (assessed from "+WindBuildingLoads.BearingName(terrain.Offset)+" in 45° steps): press Load terrain again to assess exposure and Kzt for each face; until then each face uses the governing neighbouring direction.";
  }catch(Exception ex){pressureStatus.Text=ex.Message;UpdateCc(null,null);}}
 protected override bool OptionalSavedInput(string key){return buildingKeys.Contains(key);}
}
